---@class RedPointDojo
local RedPointDojo = Class("RedPointDojo")


function RedPointDojo:__init()
    self.name = ""            --key 

    ---@type integer @ 红点数量
    self.pointNum = 0

    ---@type RedPointDojo @ 父节点
    self.parentNode = nil

    ---@type fun(sender:RedPointDojo):void @ 数量改变回调
    self.numChangeCb = nil

    ---@type table<string, RedPointDojo> @ 子节点
    self.dicChilds = {}

    ---@type boolean @ 是否上锁  当前界面不会实时刷新数据收到服务器时会上锁  让下一次数据操作无效，默认再下一次自动开锁
    self.isLock = false
end


function RedPointDojo:__delete()
    self.name        = nil
    self.pointNum    = nil
    self.parentNode  = nil
    self.numChangeCb = nil
    self.dicChilds   = nil
    self.isLock      = nil
end


---设置红点数量 数量不同会激活一次回调
---@param int integer
---@param isLoke boolean
function RedPointDojo:SetPointNum(num, isLoke)
    local logStr = string.format('修改小红点数量 [ key : %s, num : %s -> %s ]', tostring(self.name), tostring(self.pointNum), tostring(num))
    print(string.format('<color=#CCCC99>[RedPoint] %s</color>', tostring(logStr)))

    local fileName = string.format("%s_RedPoint_Log.txt", os.date("%m_%d", os.time()))
    GameUtils.WriteFile(string.format("%s", fileName), logStr, "a+")


    --除了叶节点其他节点不能调用
    if #self.dicChilds > 0 then return end

    --如果当前节点是上锁的不允许  操作数据并且自动解锁
    if self.isLock then
        self.isLock = false
    else
        self.isLock = isLoke
        if self.pointNum ~= num then
            self.pointNum = num
            if self.numChangeCb then 
                self.numChangeCb(self)
            end
            if self.parentNode then
                self.parentNode:ChangePointNum()
            end
        end
    end 
end


---@return integer
function RedPointDojo:GetPointNum()
    return self.pointNum
end


--[[
    @desc: 手动激活一次回调
    author:{author}
    time:2020-05-21 11:18:50
    --@num: 
    @return:
]]
function RedPointDojo:InvokeCallBack()
    --除了叶节点其他节点不能调用
    if #self.dicChilds > 0 then return end

    if self.numChangeCb then 
        self.numChangeCb(self)
    end
    if self.parentNode and self.parentNode.numChangeCb then
        self.parentNode.numChangeCb(self)
    end
end


--[[
    @desc 父节点红点数的重新计算 
    author:{author}
    time:2020-03-16 14:24:20
    @return:
]]
function RedPointDojo:ChangePointNum()
    local num = 0
    for k, v in pairs(self.dicChilds) do
        if v.pointNum > 0 then
            num = 1
            break
        end
        --num = num + v.pointNum
    end

    if self.pointNum ~= num then
        self.pointNum = num
        if self.numChangeCb then 
            self.numChangeCb(self) 
        end
        if self.parentNode then
            self.parentNode:ChangePointNum()
        end
    end
end


return RedPointDojo